import json, re
from typing import Any, Dict

INTENTS = ['ASK_INTENT','REQ_REPORT','CONFIRM_EXEC','RESUME_EXEC','APPROVAL',
           'QUERY_APPROVAL','QUERY_MONITOR','QUERY_OFFER','ACCEPTANCE_PLAYBACK',
           'QNA','REJECT','OUT_OF_SCOPE']
CONFIRM_WORDS = ['确认配置','确认执行','确认','同意','可以','执行吧','执行','就这么办',
                 '没问题','好的','开始','继续配置','马上执行','就这么定','可以执行']
RESUME_WORDS = ['重新执行','重跑','续跑','失败环节','从失败','重试','再来一次','重新开始']
NEGATION_WORDS = ['不同意','不确认','暂不','先不','不要执行','先别','不了','拒绝',
                  '再等等','先放一放','不执行']
INTENT_RULES = [
    ('QUERY_APPROVAL',[r'审批.{0,20}(进度|状态|单状态|到哪|到哪了|结果|意见)', r'(审批|审核).{0,6}到哪']),
    ('APPROVAL',[r'(上线|发起|提交).{0,3}(审批|审核)', r'(审批|审核).{0,3}(发起|提交|上线)']),
    ('QUERY_MONITOR',[r'(查询|查看|查).{0,20}(监控|运营|运行监控|运行情况|上线后表现|运营情况)', r'监控.{0,6}(情况|结果|告警)']),
    ('ACCEPTANCE_PLAYBACK',[r'(受理|验收)(验证|测试|结果)', r'查询受理验证', r'受理验证']),
    ('RESUME_EXEC',[r'重新执行', r'重跑', r'续跑', r'从失败.{0,6}(环节|继续)', r'失败环节', r'重试']),
    ('REQ_REPORT',[r'(提报|提交|新增|我要{0,2})(销售品|套餐|产品|需求|方案)', r'需求', r'创建.{0,4}(套餐|销售品)',
       r'(改|调整|变更|修改).{0,8}(一下|配置|方案|需求)', r'改配置',
       r'(我要|帮我|麻烦|请|现在|直接)?(配置|提报|创建|开通|办|生成)(.{0,8})(销售品|套餐|产品|方案|需求|这个|一款)',
       r'^(?:我|现在|直接)?(?:要|想)?配置(?:这个|这款|这个套餐|这款套餐)?$', r'^我要配置$']),
    ('CONFIRM_EXEC',[r'确认配置', r'确认执行', r'确认', r'同意', r'可以', r'执行吧']),
    ('QUERY_OFFER',[r'(查|查询|查看|看看|了解一下|介绍)。?.{0,10}(存量|在架|在售|现有|上架|历史).{0,8}(产品|销售品|套餐|商品)(信息|资料|规格|详情|资费|价格|在售)',
       r'(存量|在架|在售|现有|上架|历史).{0,6}(产品|销售品|套餐|商品).{0,8}(有哪|有哪些|信息|资料|规格|详情|资费|价格|在售)',
       r'(查|查询|查看|看下|了解一下).{0,12}\d{9}\b', r'\d{9}\b.{0,6}(信息|资料|详情|规格|产品|套餐)',
       r'(?:查|查询|查看|了解|介绍)。?\s*([\u4e00-\u9fa5A-Za-z0-9\-·元]{1,20}(?:套餐|卡|包|产品)).{0,6}(信息|资料|详情|在售|在架|存量)',
       r'([\u4e00-\u9fa5A-Za-z0-9\-·元]{1,20}(?:套餐|卡|包|产品)).{0,6}(在售|在架|存量信息|的信息|资料|详情)']),
    ('QNA',[r'(规范|规则|标准|怎么|如何|能否|能不能|是否|是什么|有哪些|收费|费用|资费|测试|用例|FAQ|常见|存量)']),
]
RESUME_ONLY_RULES = [r'^重新执行', r'^重跑', r'^续跑', r'^从失败']
BARE_EXEC_RE = re.compile(r'^(?:好|嗯|行|可以|就|那)?\s*执行\s*(?:吧|下|一下|！|!|。|\.)?$')
KB_RULES = [('K1',[r'规范',r'命名',r'管理办法',r'配置规范',r'规则']),('K2',[r'资费',r'费用',r'收费',r'月租',r'套餐档位',r'叠加',r'优惠']),
            ('K3',[r'测试',r'用例',r'自动化',r'验收']),('K5',[r'FAQ',r'常见问题',r'怎么',r'如何',r'能不能']),('K4',[r'存量',r'已上线',r'现有销售品',r'历史产品'])]
REQ_ID_RE = re.compile(r'PLAN\d{14,20}', re.IGNORECASE)
PRODUCT_ID_RE = re.compile(r'(?<!\d)(?:P?\d{9}|\b\d{9}\b)(?!\d)')
APPROVAL_ID_RE = re.compile(r'APPR?\d{6,20}', re.IGNORECASE)
OFFER_ID_RE = re.compile(r'(?:OFFER|OFP?)[-_]?\d{6,20}', re.IGNORECASE)
OFFER_NAME_RE = re.compile(r'([\u4e00-\u9fa5A-Za-z0-9]{1,12}(?:卡|包|产品)(?![含括围容装裹]))')
OFFER_NAME_GEN_RE = re.compile(r'([\u4e00-\u9fa5A-Za-z0-9\-·元]{1,14}套餐)')
OFFER_NAME_STOP = ['帮我','请帮','请','我要','我','查询','查看','查','给','把','下','的','和','与','和我的','修改','改','调整','变更','上传']
PRODUCT_DOC_ASK = ['如何','怎么','能否','能不能','是什么','有哪些','请问','帮我查','查一下','介绍一下']
PRODUCT_DOC_KW = ['资费档位','套餐内','套外','生效方式','退订','订购','副卡','计费周期','套餐有效','资费方案','流量结转','断网授权','续订','计费']
PRODUCT_DOC_SECTION = re.compile(r'(?:[一二三四五六七八九十]+、|（[一二三四五六七八九十]+）|\n\d+[、.．]|\s\d+[、.．])')
NAME_HINTS = ['套餐','产品','销售品','副卡','宽带','天翼','5G','流量包','权益包','加装包','语音包','会员','校园卡']
FEE_HINTS = ['元/月','月租','月费','资费','流量','语音','分钟','GB','G流量','档位','通话','短信','叠加包']
QUERY_WORDS = ['查询','查看','查一下','查查','看看','帮我查','给我查','介绍','有没有','能不能','能否','怎么','如何','是什么','有哪些','多少钱','了解','请问','问一下','存量','信息']
CONFIG_WORDS = ['提报','配置','需求','创建','新增','生成','开通','办一个','报装','上线','落地','要走配置','进入配置','做成','要办','我要办','我要提报','我要配置','配置一下']

def _clean_name(raw):
    if not raw:
        return ''
    for s in OFFER_NAME_STOP:
        if raw.startswith(s):
            return raw[len(s):]
    return raw

def _is_product_doc(m):
    if len(m) < 120 or ('？' in m) or ('?' in m):
        return False
    if sum(1 for q in PRODUCT_DOC_ASK if q in m) >= 2:
        return False
    if not PRODUCT_DOC_SECTION.search(m):
        return False
    return sum(1 for k in PRODUCT_DOC_KW if k in m) >= 2

def _is_desc_no_intent(m):
    if len(m) < 4 or len(m) > 400 or ('？' in m) or ('?' in m):
        return False
    if not any(w in m for w in NAME_HINTS):
        return False
    if sum(1 for f in FEE_HINTS if f in m) < 1:
        return False
    return not any(w in m for w in QUERY_WORDS + CONFIG_WORDS + CONFIRM_WORDS)

def _has_config(m):
    if any(w in m for w in CONFIG_WORDS + CONFIRM_WORDS):
        return True
    for p in (r'(提报|提交|新增|我要{0,2})(销售品|套餐|产品|需求|方案)', r'需求',
              r'创建.{0,4}(套餐|销售品)', r'(改|调整|变更|修改).{0,8}(一下|配置|方案|需求)', r'改配置',
              r'(我要|帮我|麻烦|请|现在|直接)?(配置|提报|创建|开通|办|生成)(.{0,8})(销售品|套餐|产品|方案|需求|这个|一款)'):
        if re.search(p, m):
            return True
    return False

async def main(args):
    p = args.params
    message = str(p.get('message') or '').strip()
    session = {}
    sj = p.get('session_json') or ''
    if isinstance(sj, str) and sj.strip():
        try:
            session = json.loads(sj)
        except Exception:
            session = {}
    if not message:
        ret: Output = {'intent':'', 'route':'NONE', 'confirmed':'false', 'needs_llm':'false',
                       'entities_json':'{}', 'llm_prompt':'', 'matched_rule':'param-missing', 'kb_target':''}
        return ret
    ents = {}
    m = REQ_ID_RE.search(message); ents['req_id'] = m.group(0).upper() if m else (session.get('req_id') or '')
    ents['product_id']=''; ents['offer_id']=''
    m = APPROVAL_ID_RE.search(message); ents['approval_id'] = m.group(0).upper() if m else (session.get('approval_id') or '')
    m = OFFER_ID_RE.search(message)
    if m: ents['offer_id'] = m.group(0)
    else: ents['offer_id'] = session.get('offer_id') or ''
    m = PRODUCT_ID_RE.search(message)
    if m: ents['product_id'] = m.group(0)
    else: ents['product_id'] = session.get('product_id') or (session.get('offer_id') or '')
    m = OFFER_NAME_RE.search(message) or OFFER_NAME_GEN_RE.search(message)
    ents['offer_name'] = _clean_name(m.group(1)) if m else (session.get('offer_name') or '')
    negated = any(w in message for w in NEGATION_WORDS)
    confirmed = (not negated) and any(w in message for w in CONFIRM_WORDS)
    resume = any(w in message for w in RESUME_WORDS)
    intent=''; matched=''
    if resume and not negated and any(re.search(pp, message) for pp in RESUME_ONLY_RULES):
        intent, matched = 'RESUME_EXEC', 'resume-only-regex'
    elif not negated and _is_product_doc(message):
        intent, matched = ('REQ_REPORT' if _has_config(message) else 'ASK_INTENT'), 'product-doc'
    elif not negated and _is_desc_no_intent(message):
        intent, matched = 'ASK_INTENT', 'product-desc-ask'
    else:
        for it, pats in INTENT_RULES:
            if it == 'CONFIRM_EXEC' and negated:
                continue
            hit = None
            for pp in pats:
                if re.search(pp, message):
                    hit = pp
                    break
            if hit:
                intent, matched = it, hit
                break
        if not intent:
            if not negated and len(message.strip()) <= 20 and BARE_EXEC_RE.match(message.strip()):
                intent, matched = 'CONFIRM_EXEC', 'bare-exec-short'
            elif negated:
                intent, matched = 'REJECT', 'negation-regex'
    needs_llm = False
    llm_prompt = ''
    if not intent:
        if any(w in message for w in ['贷款','股票','天气','笑话','你好','你是谁','自我介绍']):
            intent, matched = 'OUT_OF_SCOPE', 'keyword'
        else:
            needs_llm = True
            matched = 'llm-fallback'
            llm_prompt = json.dumps({'task':'intent_classify','user_message':message[:500],
                'allowed_intents':INTENTS,'known_entities':{k:v for k,v in ents.items() if v}},
                ensure_ascii=False)
    route = {'ASK_INTENT':'ASK','REQ_REPORT':'A','CONFIRM_EXEC':'B','RESUME_EXEC':'B',
             'APPROVAL':'C','QUERY_APPROVAL':'D1','QUERY_MONITOR':'D2','QUERY_OFFER':'D4',
             'ACCEPTANCE_PLAYBACK':'B','QNA':'QNA','REJECT':'NONE','OUT_OF_SCOPE':'NONE'}.get(intent,'NONE')
    kb = ''
    if intent == 'QNA':
        for k, pats in KB_RULES:
            if any(re.search(pp, message) for pp in pats):
                kb = k
                break
    ret: Output = {
        'intent': intent, 'route': route,
        'confirmed': 'true' if confirmed else 'false',
        'resume': 'true' if resume else 'false',
        'needs_llm': 'true' if needs_llm else 'false',
        'entities_json': json.dumps(ents, ensure_ascii=False),
        'llm_prompt': llm_prompt, 'matched_rule': matched, 'kb_target': kb,
    }
    return ret
